'use client';
import { useRouter } from 'next/navigation';
import { useSession } from '@/lib/session';

export default function BillingView() {
  const router = useRouter();
  const { status } = useSession();
  if (status === 'signed-out') {
    router.replace(`/login?next=${encodeURIComponent('/settings/billing')}`);
  }
  return <BillingForm />;
}

import Router, { useRouter } from 'next/router';

const Welcome = ({ user }) => {
  const router = useRouter();
  if (!user) void router.push('/signup');
  return <h1>Hello {user?.name}</h1>;
};
export default Welcome;

import React from 'react';
import { useHistory as useRouteHistory } from 'react-router-dom';

export function TeamGate({ mfaRequired, children }: Props) {
  const history = useRouteHistory();
  if (mfaRequired) {
    history.push('/mfa/setup');
    return null;
  }
  return <>{children}</>;
}

import { useNavigation } from '@react-navigation/native';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { useAccount } from './useAccount';

export function useRequireAccount() {
  const navigation = useNavigation<NativeStackNavigationProp<RootStack>>();
  const account = useAccount();
  if (!account) navigation.navigate('SignIn');
  return account;
}

import { useRouter } from 'expo-router';
import { Text } from 'react-native';

export default function Profile({ signedIn }: { signedIn: boolean }) {
  const { replace } = useRouter();
  if (!signedIn) replace('/sign-in');
  return <Text>Profile</Text>;
}

import { useNavigate } from 'react-router-dom';

export const Checkout = () => {
  const navigate = useNavigate();
  const cart = useCart();
  if (cart.items.length === 0) {
    navigate('/cart', { replace: true });
  }
  return <CheckoutForm cart={cart} />;
};

import { trackAnalytics } from 'app/utils/analytics';

export function InviteBanner({ organization, missing }: Props) {
  if (missing.length > 0) {
    trackAnalytics('invite_banner.viewed', { organization, count: missing.length });
  }
  return <Banner count={missing.length} />;
}

import React, { forwardRef } from 'react';
import { analytics } from '@/analytics';

export const SaleHeader = forwardRef<HTMLDivElement, Props>((props, ref) => {
  props.sale.isLive && analytics.trackEvent({ name: 'Auction pageview', slug: props.sale.slug });
  return <div ref={ref}>{props.sale.name}</div>;
});

import { useState } from 'react';
import { useTracking } from 'react-tracking';

export function useFeatureFlag(name, value) {
  const [seen, setSeen] = useState(value);
  const { trackEvent } = useTracking();
  if (seen !== value) {
    trackEvent({ flag: name, value });
    setSeen(value);
  }
  return value;
}

import React from 'react';
import { useDispatch } from 'react-redux';
import { addNotification } from '@/notifications';

export const TransactionRow = React.memo(function TransactionRow({ txn }: Props) {
  const dispatch = useDispatch();
  if (!txn.account) {
    dispatch(addNotification({ type: 'error', message: 'Account is required' }));
  }
  return <tr><td>{txn.payee}</td></tr>;
});

import { useDispatch as useReduxDispatch } from 'react-redux';
import { cartOpened } from './cartSlice';

function CartPage() {
  const dispatch = useReduxDispatch();
  dispatch(cartOpened());
  return <Cart />;
}
export default CartPage;

'use client';
import { useRouter } from '@/i18n/navigation';
import { useAppDispatch } from '@/store/hooks';
import { accountViewed } from '@/store/accountSlice';

export function AccountPage({ user }: Props) {
  const router = useRouter();
  const dispatch = useAppDispatch();
  user ? dispatch(accountViewed(user.id)) : router.push('/login');
  return <Account user={user} />;
}

import * as R from 'react';
import { trackRowShown } from '@/analytics';

export const OrderRow = R.forwardRef<HTMLTableRowElement, Props>((props, ref) => {
  trackRowShown(props.id);
  return <tr ref={ref} />;
});

import { memo as pure } from 'react';
import { trackCellShown } from '../analytics';

export const OrderCell = pure(({ id }) => {
  trackCellShown(id);
  return <td>{id}</td>;
});

import React from 'react';
import { useDispatch } from 'react-redux';

const { memo } = React;

export const OrderTotal = memo(({ total }: { total: number }) => {
  const dispatch = useDispatch();
  dispatch({ type: 'total/shown', total });
  return <td>{total}</td>;
});

import { useMemo } from 'react';
import { useDispatch } from 'react-redux';

export function SearchResults({ items, query }: Props) {
  const dispatch = useDispatch();
  const results = useMemo(() => {
    const found = items.filter((i) => i.name.includes(query));
    dispatch(searchRan({ query, count: found.length }));
    return found;
  }, [items, query, dispatch]);
  return <List items={results} />;
}

import React from 'react';
import { trackSurveyShown } from '../analytics';

export function SurveyPrompt({ survey }) {
  const [shownAt] = React.useState(() => {
    trackSurveyShown(survey.id);
    return Date.now();
  });
  return <Prompt survey={survey} since={shownAt} />;
}

import { observer } from 'mobx-react-lite';
import { useRouter } from 'next/navigation';

export const ProfileView = observer(({ store }: Props) => {
  const router = useRouter();
  if (!store.user) router.replace('/login');
  return <Profile user={store.user} />;
});

import { observer } from 'mobx-react';
import { trackCartView } from '../analytics';

export default observer(function cart({ cart }) {
  trackCartView(cart.id);
  return <CartList items={cart.items} />;
});

import { useAuth } from '../auth';

export function HomeScreen({ navigation }: Props) {
  const user = useAuth();
  if (!user) navigation.navigate('SignIn');
  return <Feed user={user} />;
}

import { withRouter } from 'react-router-dom';

function Gate(props) {
  if (!props.allowed) {
    props.history.push('/denied');
    return null;
  }
  return <div>{props.children}</div>;
}
export default withRouter(Gate);

import { useNavigate } from 'react-router-dom';

export function Private({ ok, children }: Props) {
  const navigate = useNavigate();
  return <>{!ok && navigate('/login')}{children}</>;
}

import { useRouter } from 'next/router';

export function Legacy({ ok }: Props) {
  const { replace: redirectTo } = useRouter();
  if (!ok) redirectTo('/home');
  return <p>Legacy</p>;
}

import { useRouter } from 'next/navigation';

export function BackOnRender({ expired }: Props) {
  const router = useRouter();
  return <div>{router.back()}</div>;
}

import { useNavigate } from 'react-router-dom';

export function Moved() {
  const navigate = useNavigate();
  return <p>Moved {navigate('/x')}</p>;
}

import { useDispatch } from 'react-redux';
import { loadCart } from './cartSlice';

export function CartBadge({ count }: Props) {
  const dispatch = useDispatch();
  return <span className="badge">{dispatch(loadCart())}{count}</span>;
}

import { trackView } from '@/analytics';

export const Pricing = ({ plans }: Props) => (
  <section>
    {trackView()}
    <PlanList plans={plans} />
  </section>
);

