'use client';
import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useSession } from '@/lib/session';

export default function BillingView() {
  const router = useRouter();
  const { status } = useSession();
  useEffect(() => {
    if (status === 'signed-out') router.replace('/login');
  }, [status, router]);
  return <BillingForm />;
}

import { Navigate, useNavigate } from 'react-router-dom';

export const Checkout = () => {
  const navigate = useNavigate();
  const cart = useCart();
  if (cart.items.length === 0) return <Navigate to="/cart" replace />;
  const onDone = () => navigate('/thanks');
  return <CheckoutForm cart={cart} onDone={onDone} onCancel={() => navigate(-1)} />;
};

import { useEffect, useCallback } from 'react';
import { useDispatch } from 'react-redux';
import { trackAnalytics } from 'app/utils/analytics';

export function InviteBanner({ organization, missing }: Props) {
  const dispatch = useDispatch();
  useEffect(() => {
    if (missing.length > 0) trackAnalytics('invite_banner.viewed', { organization });
  }, [organization, missing.length]);
  const dismiss = useCallback(() => {
    dispatch({ type: 'banner/dismissed' });
    trackAnalytics('invite_banner.dismissed', { organization });
  }, [dispatch, organization]);
  return <Banner onDismiss={dismiss} />;
}

import { useReducer } from 'react';

export function IssueSelection({ ids }: { ids: string[] }) {
  const [state, dispatch] = useReducer(reducer, ids, init);
  if (state.ids !== ids) {
    dispatch({ type: 'reset', ids });
  }
  return <List state={state} />;
}

import { useMemo, useState } from 'react';
import { createStore } from './store';

export const GraphiteProvider = ({ children, query }: Props) => {
  const [state, setState] = useState<State>();
  const dispatch = useMemo(() => createStore(setState), []);
  if (!state) {
    dispatch(init({ query }));
  }
  return <Context.Provider value={state}>{children}</Context.Provider>;
};

import { notFound, redirect } from 'next/navigation';

export default async function OrgPage({ params }: Props) {
  const session = await getSession();
  if (!session) redirect('/login');
  const org = await getOrg(params.slug);
  if (!org) notFound();
  return <OrgView org={org} />;
}

'use server';
import { trackPurchase } from '@/server/analytics';

function Receipt({ order }: { order: Order }) {
  trackPurchase(order.id);
  return <p>Order {order.id} placed</p>;
}

export async function completeCheckout(cartId: string) {
  const order = await placeOrder(cartId);
  return <Receipt order={order} />;
}

import { trackServerPageView } from '@/server/analytics';

export default async function DashboardPage() {
  const user = await getUser();
  trackServerPageView('dashboard', user.id);
  return <Dashboard user={user} />;
}

import { trackBannerShown } from '../analytics';

export const Basic = () => {
  trackBannerShown('story');
  return <AlertBanner />;
};

import { useHistory } from 'react-router-dom';

function Harness() {
  const history = useHistory();
  history.push('/login');
  return <LoginRedirect />;
}
it('redirects', () => cy.mount(<Harness />));

import { useDispatch } from 'react-redux';

const Template = () => {
  const dispatch = useDispatch();
  dispatch({ type: 'shortcuts/reset' });
  return <ShortcutsSettings />;
};
export default { title: 'Settings/Shortcuts' };

import { useRouter } from 'next/router';
import { trackClick } from '@/analytics';

export function Toolbar({ items }: Props) {
  const router = useRouter();
  function open(href: string) {
    trackClick(href);
    router.push(href);
  }
  return <nav>{items.map((item) => <a key={item.href} onClick={() => open(item.href)}>{item.label}</a>)}</nav>;
}

import { useHistory } from 'react-router-dom';

export function UndoBar({ past, current }: Props) {
  const location = useHistory().location;
  const history = [...past];
  history.push(current);
  return <Steps items={history} at={location.pathname} />;
}

import { track } from '@/analytics';

export function reportPageView(path: string) {
  track('page_view', { path });
}

export class Tracker {
  view(path: string) {
    track('page_view', { path });
  }
}

import { useRouter } from 'next/router';

export function Search({ query }: Props) {
  const router = useRouter();
  const href = router.asPath;
  const pending = query ? router.prefetch(`/search?q=${query}`) : null;
  return <Results href={href} pending={pending} />;
}

import { useCallback } from 'react';
import { useDispatch } from 'react-redux';

export function FilterBar({ filters }: Props) {
  const dispatch = useDispatch();
  const apply = useCallback(() => {
    dispatch(filtersChanged(filters));
  }, [dispatch, filters]);
  return <button onClick={apply}>Apply</button>;
}

import { useUndoStack } from './useUndoStack';

export function Canvas({ doc }: Props) {
  const editor = useUndoStack(doc);
  if (editor.current !== doc) editor.history.push(doc);
  return <Surface doc={doc} />;
}

import { useRouter } from 'next/router';

export function NextLink({ href, children }: Props) {
  const { prefetch: warm } = useRouter();
  warm(href);
  return <a href={href}>{children}</a>;
}

import { useRouter } from 'vue-router';
import { useSession } from './useSession';

export function useAuthGuard() {
  const router = useRouter();
  const session = useSession();
  if (!session.value) router.push('/login');
  return session;
}

import { useRouter } from 'next/navigation';
import { trackEvent } from '@/analytics';

export function BackButton({ label }: Props) {
  const router = useRouter();
  const trackTap = (name: string) => () => trackEvent({ name });
  return (
    <>
      <button onClick={() => router.back()}>{label}</button>
      <Link onPress={trackTap('help')} href="/help" />
    </>
  );
}

import { useMemo } from 'react';
import { trackMemo } from 'react-tracked';
import { useTrackedState } from './store';

export function TodoCount() {
  const state = useTrackedState();
  const done = useMemo(() => {
    trackMemo(state);
    return state.todos.filter((todo) => todo.done).length;
  }, [state]);
  return <span>{done}</span>;
}
